/* D122：共用富媒体组件。仅浏览器内存演示，不上传、不录制、不调用联网工具。 */
const mdState = {attachments:{},comments:{},transcripts:{},composers:{},serial:0,preview:null};
const mdFieldStyle = 'width:100%;box-sizing:border-box;padding:10px;border:1px solid var(--border);background:var(--card);color:var(--fg);font:inherit';
const mdPortalFiles = [
  {id:'sow',type:'word',name:'账单中心二期需求说明书.docx',size:'1.8 MB',version:'v1',text:'阶段一：账单查询。阶段二：导出与权限。阶段三：交付说明。',anchor:'第 2 段'},
  {id:'screen',type:'image',name:'导出字段截图.png',size:'248 KB',version:'v1',anchor:'图像区域'},
  {id:'voice',type:'voice',name:'导出需求语音',size:'320 KB',version:'v1',duration:40,text:'导出时请保留账期和字段顺序，审计角色不能导出金额。',anchor:'00:12–00:24'},
  {id:'pdf',type:'pdf',name:'导出字段说明.pdf',size:'720 KB',version:'v1',pages:4,text:'账期、字段顺序与导出权限说明。',anchor:'第 1 页'}
];
const mdChatFiles = [
  {...mdPortalFiles[1],id:'chat-image'},
  {id:'chat-video',type:'video',name:'导出演示.mp4',size:'8.2 MB',version:'v2',duration:72,anchor:'00:18–00:24'},
  {id:'chat-markdown',type:'markdown',name:'导出说明.md',size:'2 KB',version:'v1',text:'# 导出说明\n- 选择账期\n- 核对字段顺序\n```text\n账期,金额,税额\n```',anchor:'第 1 段'},
  {id:'chat-code',type:'code',name:'导出字段示例.js',size:'1 KB',version:'v1',text:'const fields = ["账期", "金额", "税额"];\nreturn fields.join(",");',anchor:'第 1–2 行'},
  {...mdPortalFiles[2],id:'chat-voice'}
];
const mdSearchExample = {
  query:'CSV 中文编码与字段转义',removed:true,
  results:[
    {title:'CSV 格式与转义规则',domain:'rfc-editor.org',url:'https://www.rfc-editor.org/rfc/rfc4180',summary:'包含逗号、双引号或换行的字段应使用双引号包围。'},
    {title:'通过 Excel 打开 UTF-8 CSV 文件',domain:'support.microsoft.com',url:'https://support.microsoft.com/zh-cn/search/results?query=UTF-8%20CSV',summary:'UTF-8 编码与导入方式影响中文显示，需按目标客户端验证。'},
    {title:'CSV 文本格式登记',domain:'iana.org',url:'https://www.iana.org/assignments/media-types/text/csv',summary:'CSV 是文本格式，可声明字符集参数。'}
  ],
  conclusions:[{text:'包含逗号、双引号或换行的字段需要按 CSV 规则转义。',sources:[1]},{text:'中文读取应核对编码与目标表格软件的导入方式。',sources:[2,3]}]
};
function mdEsc(mdValue){return String(mdValue==null?'':mdValue).replace(/[&<>"']/g,mdChar=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[mdChar]));}
function mdBtn(mdText,mdAction,mdKind='ghost sm',mdDisabled=false){return `<button type="button" class="btn ${mdKind}" onclick="${mdEsc(mdAction)}" ${mdDisabled?'disabled':''}>${mdText}</button>`;}
function mdTime(mdSeconds){return String(Math.floor(mdSeconds/60)).padStart(2,'0')+':'+String(Math.floor(mdSeconds%60)).padStart(2,'0');}
function mdShot(){return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="420" viewBox="0 0 800 420"><rect width="800" height="420" fill="#f1f5f9"/><rect x="32" y="32" width="736" height="356" rx="8" fill="white" stroke="#94a3b8"/><text x="60" y="80" font-size="24" fill="#0f172a">导出字段预览</text><path d="M60 112h680M60 182h680M60 252h680M60 322h680" stroke="#cbd5e1"/><g fill="#334155" font-size="20"><text x="64" y="155">账期</text><text x="310" y="155">金额</text><text x="550" y="155">税额</text><text x="64" y="225">十月</text><text x="310" y="225">1,280.00</text><text x="550" y="225">76.80</text><text x="64" y="295">九月</text><text x="310" y="295">960.00</text><text x="550" y="295">57.60</text></g><text x="64" y="360" font-size="16" fill="#64748b">原型示例截图 · 非实际客户数据</text></svg>');}
function mdHighlight(mdText){return mdEsc(mdText).replace(/\b(const|return|let|function)\b/g,'<span class="hl">$1</span>');}
function mdMarkdown(mdText){let mdCode=false,mdList=false,mdHtml='';for(const mdLine of String(mdText||'').split('\n')){if(mdLine.startsWith('```')){if(mdList){mdHtml+='</ul>';mdList=false;}mdHtml+=mdCode?'</code></pre>':'<pre class="code" style="white-space:pre-wrap;overflow-wrap:anywhere"><code>';mdCode=!mdCode;continue;}if(mdCode){mdHtml+=mdEsc(mdLine)+'\n';continue;}if(mdLine.startsWith('- ')){if(!mdList){mdHtml+='<ul>';mdList=true;}mdHtml+='<li>'+mdEsc(mdLine.slice(2))+'</li>';continue;}if(mdList){mdHtml+='</ul>';mdList=false;}const mdHeading=mdLine.match(/^(#{1,3}) (.*)$/);mdHtml+=mdHeading?`<h${mdHeading[1].length+2}>${mdEsc(mdHeading[2])}</h${mdHeading[1].length+2}>`:`<p>${mdEsc(mdLine)}</p>`;}return mdHtml+(mdList?'</ul>':'')+(mdCode?'</code></pre>':'');}
function mdAttachment(mdA){
  const mdKey=(mdA.scope||'team')+':'+mdA.id;mdState.attachments[mdKey]=mdA;if(mdState.transcripts[mdKey]!=null)mdA.text=mdState.transcripts[mdKey];
  const mdCall=mdEsc(JSON.stringify(mdKey)),mdImage=mdA.src||mdShot();let mdBody='';
  if(mdA.type==='image')mdBody=`<div class="row wrap">${mdBtn(`<img src="${mdEsc(mdImage)}" alt="${mdEsc(mdA.name)}：点击放大" style="width:100%;max-width:260px;height:auto">`,`mdZoom(${JSON.stringify(mdKey)})`)}</div><p class="muted xs">缩略图相册 · 点击同页放大</p>`;
  else if(mdA.type==='video')mdBody=`<div class="empty">${I('video')} 视频播放器占位 · ${mdTime(mdA.duration)}</div><label class="stack small">时间轴<input type="range" min="0" max="${mdA.duration}" value="0" oninput="this.nextElementSibling.textContent=mdTime(this.value)+' / ${mdTime(mdA.duration)}'"><output>00:00 / ${mdTime(mdA.duration)}</output></label><p class="muted xs">播放源未接入，当前可预览时间位置。</p>`;
  else if(mdA.type==='pdf')mdBody=`<div class="empty">PDF 分页预览占位<p>${mdEsc(mdA.text||'正文预览')}</p></div><div class="row wrap">${mdBtn('上一页','mdPage(this,-1)')}<span data-md-page="1" data-md-total="${mdA.pages||1}" aria-live="polite">第 1 / ${mdA.pages||1} 页</span>${mdBtn('下一页','mdPage(this,1)')}</div>`;
  else if(['word','excel','ppt'].includes(mdA.type))mdBody=`<div class="note info"><b>已转换预览</b><p>${mdEsc(mdA.text||'表格、演示文稿与文档预览占位')}</p></div>${mdBtn('下载原文件',`mdDownload(${JSON.stringify(mdKey)})`)}<p class="muted xs">原型无原文件，点击可查看下载可用条件。</p>`;
  else if(mdA.type==='markdown')mdBody=mdMarkdown(mdA.text);
  else if(mdA.type==='code')mdBody=`<pre class="code mono" style="white-space:pre-wrap;overflow-wrap:anywhere"><code>${mdHighlight(mdA.text)}</code></pre>`;
  else if(['audio','voice'].includes(mdA.type))mdBody=`<div class="row">${I('audio-lines')}<span class="mono" aria-label="波形占位">▂ ▅ ▃ ▇ ▄ ▂ ▆ ▃ ▅ ▂</span><b>${mdTime(mdA.duration||40)}</b></div><p class="muted xs">音频播放器与波形占位</p><details><summary>展开转写文字 · 转写可编辑</summary><label class="stack small">转写文字<textarea rows="3" style="${mdFieldStyle}" ${mdA.readonly?'disabled':''} oninput="mdState.transcripts[${mdCall}]=this.value;mdState.attachments[${mdCall}].text=this.value">${mdEsc(mdA.text)}</textarea></label>${mdA.readonly?'<p class="muted xs">你当前只读，不能编辑转写。</p>':''}</details>`;
  else mdBody=`<dl class="kv"><dt>名称</dt><dd>${mdEsc(mdA.name)}</dd><dt>大小</dt><dd>${mdEsc(mdA.size)}</dd><dt>类型</dt><dd>${mdEsc(mdA.type||'其他文件')}</dd></dl>`;
  return `<section class="stack" style="padding:12px;border:1px solid var(--border);min-width:0"><div class="row wrap"><b class="grow" style="overflow-wrap:anywhere">${mdEsc(mdA.name)}</b><span class="badge b-info">${mdEsc(mdA.version||'v1')}</span></div><span class="muted xs">${mdEsc(mdA.size||'大小待确定')} · ${mdEsc(({image:'图片',video:'视频',word:'Word 文档',excel:'Excel 表格',ppt:'PPT 演示',pdf:'PDF 文档',markdown:'Markdown 文档',code:'代码',voice:'语音',audio:'音频'})[mdA.type]||'其他文件')}</span>${mdBody}<div class="row wrap">${mdBtn('批注',`mdComment(${JSON.stringify(mdKey)})`,'ghost sm',mdA.readonly)}${mdA.teamDraft?mdBtn('加入需求草案',`mdExtract(${JSON.stringify(mdKey)})`,'sm',!mdA.draftAllowed):''}</div>${mdA.readonly?'<p class="muted xs">你当前只读，不能批注。</p>':''}${mdA.teamDraft&&!mdA.draftAllowed?'<p class="muted xs">草案已锁定；仅整理中且未签认的草案可添加需求。</p>':''}<div class="stack small">${(mdState.comments[mdKey]||[]).map(mdC=>`<div class="note info"><b>${mdEsc(mdC.anchor)} · ${mdEsc(mdC.version)}</b><p>${mdEsc(mdC.text)}</p><span class="muted xs">${mdA.scope==='portal'?'你可见的附件批注':'团队锚定批注'}</span></div>`).join('')}</div></section>`;
}
function mdPage(mdButton,mdDelta){const mdLabel=mdButton.parentElement.querySelector('[data-md-page]');const mdPageNumber=Math.max(1,Math.min(+mdLabel.dataset.mdTotal,+mdLabel.dataset.mdPage+mdDelta));mdLabel.dataset.mdPage=mdPageNumber;mdLabel.textContent=`第 ${mdPageNumber} / ${mdLabel.dataset.mdTotal} 页`;}
function mdZoom(mdKey){const mdA=mdState.attachments[mdKey];mdState.preview=mdKey;openModal(`<div class="stack" style="padding:20px"><div class="row"><b class="grow">${mdEsc(mdA.name)}</b>${mdBtn('关闭预览','mdState.preview=null;closeModal()')}</div><img src="${mdEsc(mdA.src||mdShot())}" alt="${mdEsc(mdA.name)}放大预览" style="width:100%;height:auto">${mdBtn('批注',`mdComment(${JSON.stringify(mdKey)})`,'sm',mdA.readonly)}</div>`,true);}
function mdDownload(mdKey){const mdA=mdState.attachments[mdKey];toast('原型未接入原文件存储；实际下载需附件访问权限与扫描通过：'+mdA.name);}
function mdComment(mdKey){const mdA=mdState.attachments[mdKey];if(mdA.readonly)return;openModal(`<div class="stack" style="padding:24px"><h3>附件批注</h3><p>${mdEsc(mdA.name)} · ${mdEsc(mdA.version||'v1')}</p><label class="stack">锚定位置<input id="md-anchor" style="${mdFieldStyle}" value="${mdEsc(mdA.anchor||'第 1 段')}"></label><label class="stack">批注内容<textarea id="md-comment" rows="3" style="${mdFieldStyle}"></textarea></label><p class="note info">${mdA.scope==='portal'?'仅针对你可见的附件，保留附件版本与位置。':'保留附件版本与锚点；支持页码、段落、代码行、表格行、图像区域及视频时间段。'}</p><div class="row">${mdBtn('取消','closeModal()')}${mdBtn('保存批注',`mdSaveComment(${JSON.stringify(mdKey)})`,'primary')}</div></div>`);}
function mdSaveComment(mdKey){const mdA=mdState.attachments[mdKey],mdText=document.getElementById('md-comment').value.trim(),mdAnchor=document.getElementById('md-anchor').value.trim();if(mdA.readonly||!mdText||!mdAnchor)return toast('请填写位置和批注内容');(mdState.comments[mdKey]||=[]).push({text:mdText,anchor:mdAnchor,version:mdA.version||'v1'});closeModal();route();}
function mdExtract(mdKey){const mdA=mdState.attachments[mdKey];if(!mdA.teamDraft||!mdA.draftAllowed)return;if(typeof etEditable!=='function'||!etEditable(etThread()))return toast('草案已锁定，不能加入需求');const mdT=etThread();if(mdT.mediaExtracted)return toast('已从附件抽取 6 条需求项，无需重复加入');['账期筛选','字段顺序','金额口径','角色权限','导出提示','文件命名'].forEach((mdTitle,mdIndex)=>mdT.items.push({id:'附件条目 '+(mdIndex+1),phase:'附件抽取 · 待核对',title:mdTitle,criteria:`当你使用${mdTitle}时，系统应符合附件描述；具体标准待你核对。`,priority:'待确认',ref:mdA.name+' · '+mdA.version+' · '+mdA.anchor,out:false}));mdT.mediaExtracted=true;route();toast('已从附件抽取 6 条需求项');}
function mdPortalAttachments(mdReadonly=false){return `<div class="bubble stack"><b>Lee · 甲方上传 · T1</b>${mdPortalFiles.map(mdA=>mdAttachment({...mdA,scope:'portal',readonly:mdReadonly})).join('')}</div>`;}
function mdTeamAttachments(mdEditable){return mdPortalFiles.map(mdA=>mdAttachment({...mdA,scope:'engagement',teamDraft:true,draftAllowed:mdEditable})).join('');}
function mdCitations(mdSources,mdResults){return mdSources.map(mdN=>mdResults[mdN-1]?`<sup><a href="${mdEsc(mdSafeURL(mdResults[mdN-1].url))}" target="_blank" rel="noopener noreferrer" aria-label="来源 ${mdN}：${mdEsc(mdResults[mdN-1].title)}">[${mdN}]</a></sup>`:'').join('');}
function mdSafeURL(mdURL){try{const mdParsed=new URL(mdURL);return ['https:','http:'].includes(mdParsed.protocol)?mdParsed.href:'#';}catch{return '#';}}
function mdSearchCard(mdS){return `<div class="decision-card stack"><div class="row wrap"><b class="grow">联网搜索结果</b><span class="badge ${mdS.pending?'b-warn':'b-info'}">${mdS.pending?'待批准 · 甲方不可见':'来源引用'}</span></div><dl class="kv"><dt>查询词</dt><dd>${mdEsc(mdS.query)}</dd></dl>${mdS.removed?'<div class="note info">已移除保密内容：项目名、客户名</div>':''}<ol>${mdS.results.slice(0,5).map(mdR=>`<li><a href="${mdEsc(mdSafeURL(mdR.url))}" target="_blank" rel="noopener noreferrer">${mdEsc(mdR.title)}</a><span class="muted xs"> · ${mdEsc(mdR.domain)}</span><p>${mdEsc(mdR.summary)}</p></li>`).join('')}</ol><div><b>结论</b>${mdS.conclusions.map(mdC=>`<p>${mdEsc(mdC.text)}${mdCitations(mdC.sources,mdS.results)}${!mdC.sources.length?'<span class="badge b-danger">缺少来源 · 不作为结论</span>':''}</p>`).join('')}</div><div class="note warn">无来源的结论不算数</div><p class="muted xs">本次搜索已记入审计${mdS.pending?'（原型样例）':''}</p></div>`;}
function mdApprovedAnswer(){return `<div class="bubble stack"><div class="row wrap"><b>AI 助手</b><span class="badge b-ok">已由对接人批准发送</span></div><p>导出内容包含逗号或换行时，需要按 CSV 规则转义。${mdCitations([1],mdSearchExample.results)}</p><p>中文文件需核对编码与表格软件的导入方式。${mdCitations([2,3],mdSearchExample.results)}</p><details><summary>查看引用来源</summary>${mdSearchCard({...mdSearchExample,removed:false})}</details><p class="muted xs">范围、日期与价格由对接人确认。</p></div>`;}
function mdComposer(mdID){return mdState.composers[mdID];}
function mdComposerTools(mdCtx){
  const mdID=mdCtx.id;if(!/^[a-z0-9-]+$/i.test(mdID))return '';const mdOld=mdComposer(mdID)||{};mdState.composers[mdID]={...mdOld,ctx:mdCtx,search:!!mdOld.search&&!!mdCtx.authorized};const mdS=mdComposer(mdID),mdDisabled=!!mdCtx.disabled;
  return `<div id="md-tools-${mdID}" class="stack" style="padding:10px 0" ondragover="event.preventDefault()" ondrop="mdDrop(event,'${mdID}')" onpaste="mdPaste(event,'${mdID}')"><div class="row wrap"><input id="md-files-${mdID}" type="file" multiple hidden onchange="mdUpload('${mdID}',this.files);this.value=''" ${mdDisabled?'disabled':''}>${mdBtn(I('paperclip')+'附件',`document.getElementById('md-files-${mdID}').click()`,'sm',mdDisabled)}<button type="button" class="btn sm" ${mdDisabled?'disabled':''} onpointerdown="mdRecordStart(event,'${mdID}')" onpointerup="mdRecordStop('${mdID}')" onpointercancel="mdRecordCancel('${mdID}')" onlostpointercapture="mdRecordStop('${mdID}')" onkeydown="if((event.key===' '||event.key==='Enter')&&!event.repeat)mdRecordStart(event,'${mdID}')" onkeyup="if(event.key===' '||event.key==='Enter')mdRecordStop('${mdID}')" onblur="mdRecordStop('${mdID}')">${I('mic')}按住说话</button>${mdCtx.team?`<label class="row small"><input type="checkbox" ${mdS.search?'checked':''} ${!mdCtx.authorized||mdDisabled?'disabled':''} onchange="mdToggleSearch('${mdID}',this.checked)">联网搜索</label><span class="muted xs">来自工具目录 · 本项目${mdCtx.authorized?'已授权':'未授权'}</span>`:''}</div>${mdCtx.team&&!mdCtx.authorized?'<p class="note warn">默认关闭；本项目 / 当前角色未获授权，不能使用联网搜索。</p>':''}${mdDisabled?`<p class="note warn">${mdEsc(mdCtx.reason||'当前会话只读，不能上传或录音。')}</p>`:''}<p class="muted xs">可多选附件；拖拽到此处或在消息框粘贴截图。单个附件上限 25 MB · 上传后须病毒扫描通过。</p><details><summary>上传状态预览</summary><div class="row wrap">${['正常','异常','空'].map(mdMode=>`<button type="button" class="chip" ${mdDisabled?'disabled':''} onclick="mdUploadPreview('${mdID}','${mdMode}')">${mdMode}</button>`).join('')}</div><p class="muted xs">异常演示病毒扫描失败；空状态清空演示队列。不会上传真实文件。</p></details><div id="md-status-${mdID}" role="status" aria-live="polite">${mdS.recording?'录音中…':mdS.status?mdEsc(mdS.status):''}</div><div id="md-queue-${mdID}" class="stack">${mdQueue(mdID)}</div><div id="md-transcript-${mdID}">${mdTranscript(mdID)}</div><div id="md-search-${mdID}">${mdS.search&&!mdDisabled?mdSearchControls(mdID):''}</div></div>`;
}
function mdUploadPreview(mdID,mdMode){const mdS=mdComposer(mdID);if(!mdS||mdS.ctx.disabled)return;mdS.failure=mdMode==='异常';if(mdMode==='空'){mdS.files=[];mdRefreshQueue(mdID);mdStatus(mdID,'暂无附件');return;}mdUpload(mdID,[{name:mdMode==='异常'?'扫描失败示例.pdf':'需求说明示例.pdf',size:1024}]);}
function mdQueue(mdID){return (mdComposer(mdID).files||[]).map(mdF=>`<div class="stack small"><span>${mdEsc(mdF.name)} · ${mdEsc(mdF.status)}</span><div class="progress" role="progressbar" aria-label="${mdEsc(mdF.name)}上传进度" aria-valuenow="${mdF.progress}" aria-valuemin="0" aria-valuemax="100"><div style="width:${mdF.progress}%"></div></div></div>`).join('');}
function mdRefreshQueue(mdID){const mdEl=document.getElementById('md-queue-'+mdID);if(mdEl)mdEl.innerHTML=mdQueue(mdID);}
function mdUpload(mdID,mdFiles){const mdS=mdComposer(mdID);if(!mdS||mdS.ctx.disabled)return;for(const mdF of Array.from(mdFiles)){const mdFailure=!!mdS.failure;const mdItem={name:mdF.name,progress:0,status:mdF.size>25*1024*1024?'超限：单个附件不得超过 25 MB':'上传中（原型模拟）'};(mdS.files||=[]).push(mdItem);if(mdF.size>25*1024*1024)continue;let mdProgress=0;const mdTimer=setInterval(()=>{mdProgress+=25;mdItem.progress=mdProgress;mdRefreshQueue(mdID);if(mdProgress>=100){clearInterval(mdTimer);mdItem.status='病毒扫描中…（原型模拟）';mdRefreshQueue(mdID);setTimeout(()=>{mdItem.status=mdFailure?'病毒扫描失败：已隔离，禁止发送与预览':'病毒扫描通过 · 待随消息发送（原型样例）';mdRefreshQueue(mdID);},650);}},200);}mdRefreshQueue(mdID);}
function mdDrop(mdEvent,mdID){mdEvent.preventDefault();mdUpload(mdID,mdEvent.dataTransfer.files);}
function mdPaste(mdEvent,mdID){const mdFiles=Array.from(mdEvent.clipboardData?.items||[]).filter(mdItem=>mdItem.kind==='file').map(mdItem=>mdItem.getAsFile()).filter(Boolean);if(mdFiles.length){mdEvent.preventDefault();mdUpload(mdID,mdFiles);}}
function mdStatus(mdID,mdText){const mdS=mdComposer(mdID);mdS.status=mdText;const mdEl=document.getElementById('md-status-'+mdID);if(mdEl)mdEl.textContent=mdText;}
function mdRecordStart(mdEvent,mdID){const mdS=mdComposer(mdID);if(!mdS||mdS.ctx.disabled||mdS.recording||mdS.transcribing)return;mdEvent.preventDefault();if(mdEvent.pointerId!=null)mdEvent.currentTarget.setPointerCapture(mdEvent.pointerId);mdS.recording=true;mdS.started=Date.now();mdStatus(mdID,'录音中 · 00:00（原型模拟）');mdS.timer=setInterval(()=>mdStatus(mdID,'录音中 · '+mdTime((Date.now()-mdS.started)/1000)+'（原型模拟）'),250);}
function mdRecordCancel(mdID){const mdS=mdComposer(mdID);if(!mdS?.recording)return;clearInterval(mdS.timer);mdS.recording=false;mdStatus(mdID,'录音已取消');}
function mdRecordStop(mdID){const mdS=mdComposer(mdID);if(!mdS?.recording)return;clearInterval(mdS.timer);mdS.recording=false;mdS.transcribing=true;mdStatus(mdID,'转写中…');setTimeout(()=>{mdS.transcribing=false;mdS.transcript='请按账期导出，并保留模板中的字段顺序。';mdStatus(mdID,'转写完成 · 转写可编辑（示例文字，未实际录音）');const mdEl=document.getElementById('md-transcript-'+mdID);if(mdEl)mdEl.innerHTML=mdTranscript(mdID);},900);}
function mdTranscript(mdID){const mdS=mdComposer(mdID);return mdS.transcript?`<label class="stack small">转写可编辑<textarea rows="2" style="${mdFieldStyle}" oninput="mdComposer('${mdID}').transcript=this.value" ${mdS.ctx.disabled?'disabled':''}>${mdEsc(mdS.transcript)}</textarea></label>${mdBtn('加入消息',`mdUseTranscript('${mdID}')`,'sm',mdS.ctx.disabled)}`:'';}
function mdUseTranscript(mdID){const mdS=mdComposer(mdID),mdEl=document.getElementById(mdS.ctx.input);if(mdS.ctx.disabled||!mdEl||!mdS.transcript)return;mdEl.value+=(mdEl.value?'\n':'')+mdS.transcript;mdEl.dispatchEvent(new Event('input',{bubbles:true}));toast('转写文字已加入消息，请核对后发送');}
function mdToggleSearch(mdID,mdEnabled){const mdS=mdComposer(mdID);if(!mdS.ctx.team||!mdS.ctx.authorized||mdS.ctx.disabled)return;mdS.search=mdEnabled;document.getElementById('md-search-'+mdID).innerHTML=mdEnabled?mdSearchControls(mdID):'';}
function mdSearchControls(mdID){return `<div class="note info stack"><p>搜索默认关闭。查询自动移除项目名、客户名及内部数据；不提供保密内容外发许可。</p><label class="stack">查询词<input id="md-query-${mdID}" style="${mdFieldStyle}" value="CSV 中文编码与字段转义"></label>${mdBtn('预览搜索',`mdRunSearch('${mdID}')`,'sm')}<p class="muted xs">示例结果不代表实时检索；每次搜索应记入审计。</p><div id="md-results-${mdID}"></div></div>`;}
function mdRunSearch(mdID){const mdS=mdComposer(mdID);if(!mdS.ctx.team||!mdS.ctx.authorized||!mdS.search||mdS.ctx.disabled)return;const mdRaw=document.getElementById('md-query-'+mdID).value.trim();if(!mdRaw)return toast('请填写查询词');/* 自由输入不外发；固定公开样例避免保密查询泄漏。 */document.getElementById('md-results-'+mdID).innerHTML=mdSearchCard({...mdSearchExample,removed:true,pending:true});mdStatus(mdID,'仅预览公开查询样例，输入内容未联网发送；本次搜索已记入审计（原型模拟）');}
